//! The message material schema: one schema, three projections (prost
//! binary, pbjson JSON, hex anchor rows). Deliberately stdio-free:
//! link contracts live in `zconned-stdio-types`.

// Generated by [`prost-build`]
include!(concat!(env!("OUT_DIR"), "/zconn.zconned.material.rs"));
// Generated by [`pbjson-build`]
include!(concat!(env!("OUT_DIR"), "/zconn.zconned.material.serde.rs"));

use prost::Message as _;
use zconned_crypto::DIGEST_LEN;

/// The resource digest: H(canonical proto3 Value{kind, data}).
// The proto3 encoding (tag+len) is self-delimiting = injective: the
// kind is bound to the value. The recipe is pinned forever.
pub fn resource_digest(kind: &str, data: &[u8]) -> [u8; DIGEST_LEN] {
    let value = Value {
        kind: kind.to_owned(),
        data: data.to_vec(),
    };
    zconned_crypto::digest(&value.encode_to_vec())
}

/// Kinds whose values the core stamps at commit (interface-supplied
/// values are overwritten). Day-one = the commit timestamp. The
/// `vnd.zconn.*` prefix is reserved for core-attested kinds.
pub const CLAIM_KIND_TS: &str = "application/vnd.zconn.ts";

#[cfg(test)]
mod tests {
    use super::*;
    use pretty_assertions::assert_eq;

    fn sample_msg() -> Msg {
        Msg {
            ver_major: 1,
            ver_minor: 0,
            prev: vec![MsgRef {
                ver_major: 1,
                ver_minor: 0,
                algo: "sha3-256".to_owned(),
                digest: vec![0xab; 32],
            }],
            content: Some(ResourceRef {
                algo: "sha3-256".to_owned(),
                digest: resource_digest("text/plain", b"hello").to_vec(),
            }),
            claims: vec![Claim {
                kind: "application/vnd.zconn.ts".to_owned(),
                r#ref: Some(ResourceRef {
                    algo: "sha3-256".to_owned(),
                    digest: resource_digest("application/vnd.zconn.ts", b"2026-11-05T12:00:00Z")
                        .to_vec(),
                }),
            }],
        }
    }

    #[test]
    fn ver_minor_zero_is_omitted_on_the_wire() {
        let mut msg = sample_msg();
        let with_zero = msg.encode_to_vec();
        msg.ver_minor = 1;
        let with_one = msg.encode_to_vec();
        // Field 2 (tag + varint) appears only when non-zero.
        assert_eq!(with_one.len(), with_zero.len() + 2);
    }

    #[test]
    fn material_roundtrips_through_transport_bytes() {
        let msg = sample_msg();
        let bytes = msg.encode_to_vec();
        assert_eq!(Msg::decode(bytes.as_slice()).unwrap(), msg);
    }

    #[test]
    fn canonical_profile_encoding_is_byte_exact() {
        // Pins the canonical profile: proto3, implicit presence,
        // field-number order, prost emission (protocol.md).
        let msg = sample_msg();
        let mut expected = vec![
            0x08, 0x01, // field 1: ver_major = 1
        ];
        // field 3: prev, length-delimited MsgRef
        let ref_bytes = msg.prev[0].encode_to_vec();
        expected.push(0x1a);
        expected.push(ref_bytes.len() as u8);
        expected.extend_from_slice(&ref_bytes);
        // field 4: content, length-delimited ResourceRef
        let content_bytes = msg.content.as_ref().unwrap().encode_to_vec();
        expected.push(0x22);
        expected.push(content_bytes.len() as u8);
        expected.extend_from_slice(&content_bytes);
        // field 5: claims, length-delimited ClaimRefs in field order
        for claim in &msg.claims {
            let claim_bytes = claim.encode_to_vec();
            expected.push(0x2a);
            expected.push(claim_bytes.len() as u8);
            expected.extend_from_slice(&claim_bytes);
        }
        assert_eq!(msg.encode_to_vec(), expected);
    }

    #[test]
    fn resource_digest_recipe_is_the_canonical_body_hash() {
        // Pins the recipe: digest = H(prost-encoded Value{kind, data}).
        let value = Value {
            kind: "text/plain".to_owned(),
            data: b"hello".to_vec(),
        };
        let want = zconned_crypto::digest(&value.encode_to_vec());
        assert_eq!(resource_digest("text/plain", b"hello"), want);
    }

    #[test]
    fn resource_digest_is_injective_over_kind_plus_data() {
        // The whole point of hashing the kind IN: same bytes under
        // different kinds address different resources.
        let a = resource_digest("text/plain", b"hello");
        let b = resource_digest("text/markdown", b"hello");
        let c = resource_digest("text/plain", b"hell");
        let d = resource_digest("ab", b"c");
        let e = resource_digest("a", b"bc");
        assert_ne!(a, b);
        assert_ne!(a, c);
        assert_ne!(d, e, "the concatenation must be self-delimiting");
    }

    #[test]
    fn json_projection_roundtrips() {
        let msg = sample_msg();
        let json = serde_json::to_value(&msg).unwrap();
        let back: Msg = serde_json::from_value(json).unwrap();
        assert_eq!(back, msg);
    }

    #[test]
    fn json_projection_uses_camel_keys_and_base64_bytes() {
        let msg = sample_msg();
        let json = serde_json::to_value(&msg).unwrap();
        assert_eq!(json["verMajor"], 1);
        assert!(json.get("verMinor").is_none()); // 0 omitted
        // The record carries ADDRESSES, not values: no kind on the
        // content, digests as base64 bytes.
        assert!(json["content"].get("kind").is_none());
        assert_eq!(json["content"]["algo"], "sha3-256");
        assert_eq!(json["claims"][0]["kind"], "application/vnd.zconn.ts");
    }
}
